"""Explain exclusive writer/access assertions and scoped bit combinations."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1665': ('게시판에 글을 고치는 사람은 한 명만 있어야 하지만 구경하는 사람은 여럿이어도 된다고 약속할 수 있어요. 약속을 점검하는 것과 다른 사람을 실제로 막는 것은 달라요.', '단일 writer 검사와 실제 잠금의 역할을 구별합니다.', 'writer A / reader B / writer C를 적으세요. EXCLUSIVE_WRITER는 B의 읽기는 허용하고 C의 동시 쓰기는 위반으로 본다고 표시하세요.', ['writer는 값을 쓰는 실행 흐름이고 reader는 값을 읽는 실행 흐름이에요. concurrent는 시간이 겹쳐 진행된다는 뜻이에요. ASSERT_EXCLUSIVE_WRITER는 같은 대상에 다른 동시 writer가 없어야 한다는 조건을 KCSAN에 알려요.', 'assertion은 이 조건이 맞아야 한다고 명시해 검사하는 표시예요. 불변 조건은 코드가 지켜야 하는 약속을 뜻해요. 이 경우 다른 reader는 허용해요. 모든 접근을 금지하는 조건과는 달라요.', '매크로는 &(var)라는 대상 주소, sizeof(var)라는 크기, KCSAN_ACCESS_ASSERT라는 표시를 직접 검사 함수에 전달해요. ASSERT의 값은 8이에요. 이 호출이 var에 새 값을 쓰거나 잠금을 획득하는 것은 아니에요.', 'READ_ONCE와 WRITE_ONCE는 접근을 컴파일러가 함부로 바꾸는 일을 제한하는 도구예요. 이런 표시가 된 접근끼리는 보통의 data race 분류로 잡히지 않아도 한 명만 쓰기로 한 규칙을 어길 수 있어요. 데이터 레이스라는 특정 분류와 프로그램의 모든 동시 실행 오류는 같은 범위가 아니에요.', '예를 들어 A가 writer 전용 잠금을 잡고 42를 쓰는데 C가 그 잠금을 무시하고 WRITE_ONCE로 1을 쓰면 단일 writer 약속을 어겨요. 두 코드에 WRITE_ONCE가 있어도 잠금을 공유해 지킨 것이 아니에요. assertion은 이런 상위 규칙을 검사하려는 것이에요.', '원문 예시는 잠금 획득 → assertion → WRITE_ONCE → 잠금 해제 순서예요. reader는 예시의 규칙에 따라 잠금 없이 READ_ONCE할 수 있어요. 이 허용을 다른 모든 자료구조의 읽기에도 그대로 적용하지 말고 각각의 동기화·수명 규칙을 확인하세요.'], [('EXCLUSIVE_WRITER는 다른 reader의 동시 읽기도 금지하나요?', ['네. 모든 읽기와 쓰기를 금지해요', '아니요. 다른 reader는 허용해요'], '정답은 두 번째예요. 조건은 다른 동시 쓰기가 없어야 한다는 것이에요. 읽기까지 없어야 한다는 EXCLUSIVE_ACCESS와 구별하세요.'), ('WRITE_ONCE를 쓴 두 writer의 위반도 별도 assertion으로 살펴보는 이유는 무엇인가요?', ['표시된 접근이라 일반 data race 검사만으로 단일 writer 규칙 위반을 놓칠 수 있어서예요', 'WRITE_ONCE가 필요한 모든 잠금을 제공해서예요'], '정답은 첫 번째예요. 접근을 표시하는 것과 한 명만 쓰도록 지키는 약속은 달라요. assertion은 그 약속을 명시하며 실제 writer 잠금은 여전히 필요해요.')]), 'os1666': ('복도 한 지점에서만 확인하는 대신 방에 머무는 구간을 점검 대상으로 등록할 수 있어요. 검사 구간을 넓혀도 잘못 바뀐 물건을 자동으로 되돌려 주는 것은 아니에요.', 'scoped writer의 검사 기간과 24라는 비트 조합을 이해합니다.', 'ASSERT=01000과 SCOPED=10000을 합쳐 11000=24를 적으세요. 등록 → 42 저장 → 같은 구간의 작업 → 검사 종료를 그리세요.', ['scoped writer assertion은 선언한 지점부터 해당 스코프를 벗어날 때까지 다른 writer가 없어야 한다는 조건을 등록해요. 스코프는 지역 변수가 속한 코드 범위이며 보통 중괄호 블록으로 볼 수 있어요.', '검사 종류에는 ASSERT=8과 SCOPED=16을 함께 써요. 비트 OR로 01000 | 10000 = 11000, 십진수로 24예요. WRITE 비트를 더한 원자적 쓰기 표시 5와는 다른 목적의 조합이에요.', 'writer라는 이름인데 WRITE 비트가 없다는 점이 헷갈릴 수 있어요. 이 assertion은 검사에서 읽기 쪽 형태로 다른 쓰기와의 충돌을 찾고, 다른 읽기는 허용해요. 이름은 검사하는 조건을 뜻하며 직접 데이터를 쓰라는 명령이 아니에요.', '원문 예시는 잠금을 잡고 scoped 검사를 시작한 뒤 shared_foo에 42를 써요. 같은 구간의 뒤에서도 42가 유지되어야 해요. 잘못된 다른 writer가 중간에 1을 쓰면 이 기대를 어기는 것이에요.', '한 지점에만 assertion을 놓는 것보다 구간을 등록하면 중간 상태 변화로 생긴 문제를 찾을 기회가 늘어요. 그러나 모든 실행의 모든 오류를 반드시 찾아낸다는 보장은 아니에요. 등록 기간과 실제 검출의 완전성을 구별하세요.', '스코프가 끝나면 cleanup을 통해 검사 등록을 종료해요. 데이터가 42에서 1로 잘못 바뀌었어도 종료가 42를 다시 써 주지는 않아요. rollback은 변경을 되돌리는 기능인데 이 검사 종료는 그런 기능이 아니에요.'], [('scoped writer assertion의 기본 type 조합은 무엇인가요?', ['WRITE와 ATOMIC을 합친 5예요', 'ASSERT와 SCOPED를 합친 24예요'], '정답은 두 번째예요. ASSERT=8과 SCOPED=16을 OR하면 24예요. 원자적 쓰기 5와 구간 동안 다른 writer가 없는지 검사하는 24는 다른 표시예요.'), ('scoped assertion이 끝나면 잘못 바뀐 공유 값도 자동 복원되나요?', ['아니요. 해당 검사 등록을 종료해요', '네. 처음 값으로 자동 rollback해요'], '정답은 첫 번째예요. cleanup이 연결하는 함수는 kcsan_end_scoped_access예요. 검사 구간을 끝낼 뿐 대상 데이터를 복사해 두었다가 복구하는 기능은 없어요.')]), 'os1667': ('물건을 정리해 다음 사람이 쓰게 준비할 때는 다른 사람이 읽기만 하더라도 끼어들면 안 되는 경우가 있어요. 한 명만 쓰기와 아무도 접근하지 않기는 다른 약속이에요.', '독점 접근 조건과 객체 재사용·해제 검사를 구별합니다.', '마지막 참조 판단 → EXCLUSIVE_ACCESS 검사 → 정리 → 재사용 준비를 그리세요. 다른 reader와 writer 둘 다 위반 대상으로 표시하세요.', ['ASSERT_EXCLUSIVE_ACCESS는 다른 실행 흐름의 읽기와 쓰기가 모두 없어야 한다는 조건을 검사해요. 앞 수업의 EXCLUSIVE_WRITER는 다른 읽기를 허용했지만 여기서는 허용하지 않아요.', '전달하는 type은 WRITE=1과 ASSERT=8을 합친 9예요. 검사에서 쓰기 쪽 형태로 나타내면 다른 읽기와 쓰기를 모두 충돌 검사 대상으로 표현할 수 있어요. 이 비트를 전달한다고 검사 대상에 실제 값을 덮어쓰는 것은 아니에요.', '객체는 메모리에 담긴 하나의 데이터 묶음이에요. 참조 수는 그 객체를 사용하는 쪽을 세는 데 쓰는 값이에요. 원문 예시는 refcount_dec_and_test가 마지막 참조가 내려갔음을 나타낸 뒤 독점 접근을 기대하는 경우예요.', '그 다음 assertion으로 조건을 확인하고 객체를 정리한 뒤 재사용하도록 넘겨요. 여기서는 객체가 실제로 free되어 사라진 경우와 구별해요. 다른 사용자나 잘못 남은 포인터가 없다는 전체 수명 규칙도 올바르게 지켜져야 해요.', 'use-after-free는 이미 해제한 메모리를 여전히 사용하는 오류예요. 원문은 실제 해제 뒤의 이런 오류를 찾는 데 KASAN이 더 알맞다고 설명해요. KASAN은 메모리 접근의 유효성 문제를 찾는 검사 도구이고 KCSAN의 동시 접근 조건 검사와 초점이 달라요.', 'assertion을 부른다고 객체를 다시 할당하거나 잘못된 포인터를 안전하게 고쳐 주지는 않아요. 실제 독점 조건을 만드는 동기화와 참조 관리가 먼저 필요해요. 검사는 그 조건이 깨지는 문제를 찾도록 돕는 역할이에요.'], [('EXCLUSIVE_ACCESS는 다른 reader의 동시 접근을 허용하나요?', ['네. 다른 writer만 금지해요', '아니요. 다른 reader와 writer 모두 없어야 해요'], '정답은 두 번째예요. ACCESS는 읽기·쓰기 모두 없는 조건이고 WRITER는 다른 쓰기만 없는 조건이에요. 이름이 비슷해도 검사할 약속의 범위가 달라요.'), ('원문은 실제 free 뒤의 use-after-free를 찾는 데 어느 도구가 더 알맞다고 하나요?', ['KASAN이에요', '이 assertion이 객체를 자동 재할당해요'], '정답은 첫 번째예요. 해제 뒤 잘못된 메모리 사용은 KASAN이 더 적합하다고 설명해요. assertion은 재할당 함수가 아니므로 객체를 되살리지 않아요.')]), 'os1668': ('작업방을 쓰는 동안 다른 사람이 들어오지 않아야 한다는 조건을 점검할 수 있어요. 조건을 점검하는 표지와 실제 출입을 막는 자물쇠는 서로 달라요.', 'scoped access의 25와 검사 수명을 이해합니다.', 'WRITE=00001, ASSERT=01000, SCOPED=10000을 합쳐 11001=25를 적으세요. writer scoped의 11000=24와 마지막 비트를 비교하세요.', ['ASSERT_EXCLUSIVE_ACCESS_SCOPED는 등록한 지점부터 해당 코드 범위를 벗어날 때까지 다른 reader나 writer가 없어야 한다는 조건을 검사해요. scoped는 그 조건을 한 번의 요청보다 긴 구간에 걸쳐 등록한다는 뜻이에요.', 'type은 WRITE=1, ASSERT=8, SCOPED=16을 함께 켜요. 서로 다른 비트 칸을 OR하면 00001 | 01000 | 10000 = 11001, 즉 25예요.', 'writer scoped의 값 24와 비교하면 WRITE 비트 1이 더 있어요. writer 검사는 다른 읽기를 허용하지만 access 검사는 읽기도 허용하지 않으므로 쓰기 쪽 검사 형태를 써요. 그 비트가 대상 데이터에 실제 쓰기를 수행하라는 명령은 아니에요.', '두 scoped 매크로는 같은 내부 도우미를 사용해 지역 검사 구조체를 만들고 begin으로 등록해요. __COUNTER__를 이용한 이름으로 여러 선언이 겹치지 않게 하고 cleanup으로 범위 끝의 end를 연결해요.', '예를 들어 A가 어떤 객체를 정리하는 구간에서 다른 작업 B가 읽는다면 이 독점 조건에 어긋나요. assertion은 그 조건 위반을 살펴보지만 B의 CPU를 물리적으로 정지시키지 않아요. 실제 접근 제한은 다른 동기화 규칙이 제공해야 해요.', '종료 시 정리하는 것은 검사 등록이에요. 공유 객체의 수명과 잠금은 별도로 관리해야 해요. 숫자 24와 25를 외우기보다 허용할 상대가 reader인지 writer인지, 어느 기간을 검사하는지부터 적어 보세요.'], [('scoped access assertion의 type 값은 얼마인가요?', ['ASSERT와 SCOPED만 합친 24예요', 'WRITE·ASSERT·SCOPED를 합친 25예요'], '정답은 두 번째예요. 1 | 8 | 16 = 25예요. 24는 다른 읽기를 허용하는 writer scoped이고 access scoped는 WRITE 비트도 사용해 다른 읽기까지 검사 대상으로 표현해요.'), ('scoped access assertion이 다른 CPU의 reader를 실제로 멈추나요?', ['아니요. 독점 접근 조건을 검사해요', '네. 모든 CPU를 멈추는 실행 제어 함수예요'], '정답은 첫 번째예요. 검사 등록과 실행 제어는 달라요. 다른 접근을 실제로 막거나 없게 만드는 잠금·참조 관리 등의 규칙은 별도로 필요해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_412.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
